insert into public.minerals (name, slug, formula, crystal_system, chemical_class, rarity, hardness, hardness_max, density, density_max, colors, luster, cleavage, streak, transparency, fracture, fluorescence, habit, formation, etymology, varieties, confusions, description, mineral_group, is_group, publication_status) values
  ('Kamacite', 'kamacite', '(Fe,Ni)', 'Cubique', 'Éléments natifs', 'rare', 4, 4, 7.9, 8.2, array['gris acier','argenté']::text[], 'métallique', 'aucun', 'gris', 'opaque', 'crochue', null, 'Lamelles dans les météorites ferreuses.', 'Météorites ferreuses (octaédrites) ; très rare sur Terre.', 'Du grec kamax (perche, barre), pour ses lamelles en barres.', null, 'Taénite : plus riche en nickel, plus claire.', 'Alliage naturel de fer et de nickel (5 à 7 % de nickel) des météorites ferreuses. Associé à la taénite, il dessine les figures de Widmanstätten que révèle une attaque à l''acide.', null, false, 'published'),
  ('Taénite', 'taenite', '(Fe,Ni)', 'Cubique', 'Éléments natifs', 'rare', 5, 5.5, 7.8, 8.2, array['gris argenté','blanc d''acier']::text[], 'métallique', 'aucun', 'gris', 'opaque', 'crochue', null, 'Fins rubans entre les lamelles de kamacite.', 'Météorites ferreuses.', 'Du grec tainia (ruban), pour ses fins rubans.', null, 'Kamacite : moins riche en nickel, plus terne.', 'Alliage fer-nickel riche en nickel (de 25 à 65 %) qui dessine, autour de la kamacite, les rubans brillants des figures de Widmanstätten.', null, false, 'published'),
  ('Troilite', 'troilite', 'FeS', 'Hexagonal', 'Sulfures et sulfosels', 'rare', 3.5, 4, 4.6, 4.8, array['bronze','brun bronze']::text[], 'métallique', 'aucun', 'gris noir', 'opaque', 'irrégulière', null, 'Nodules et grains dans les météorites ferreuses.', 'Météorites (fer et chondrites), roches lunaires ; très rare sur Terre.', 'De Domenico Troili (1722-1792), qui décrivit en 1766 la météorite d''Albareto.', null, 'Pyrrhotite : moins pure, souvent magnétique.', 'Sulfure de fer pur, présent dans presque toutes les météorites et jusque dans les roches lunaires.', null, false, 'published'),
  ('Schreibersite', 'schreibersite', '(Fe,Ni)₃P', 'Quadratique', 'Éléments natifs', 'rare', 6.5, 6.5, 7.0, 7.3, array['argenté à jaune bronze']::text[], 'métallique', 'parfait', 'gris noir', 'opaque', 'irrégulière', null, 'Lames et baguettes dans les météorites ferreuses.', 'Météorites ferreuses.', 'De Carl von Schreibers (1775-1852), directeur du cabinet impérial d''histoire naturelle de Vienne.', null, 'Kamacite : plus tendre.', 'Phosphure de fer et de nickel des météorites, qui fournit aux planétologues l''une des sources possibles de phosphore de la Terre primitive.', null, false, 'published'),
  ('Lonsdaléite', 'lonsdaleite', 'C', 'Hexagonal', 'Éléments natifs', 'tres_rare', 7, 8, 3.2, 3.3, array['brun jaune','incolore']::text[], 'adamantin', 'aucun', 'blanc', 'translucide', 'irrégulière', null, 'Agrégats microscopiques.', 'Cratères d''impact et météorites à diamants (Canyon Diablo, Popigaï).', 'De Kathleen Lonsdale (1903-1971), cristallographe britannique.', null, 'Diamant : cubique.', 'Variante hexagonale du carbone, formée par le choc d''une météorite sur du graphite. Elle n''existe qu''en cristaux microscopiques.', null, false, 'published'),
  ('Sylvanite', 'sylvanite', '(Au,Ag)₂Te₄', 'Monoclinique', 'Sulfures et sulfosels', 'rare', 1.5, 2, 8.0, 8.2, array['blanc d''argent','jaune pâle']::text[], 'métallique', 'parfait', 'gris', 'opaque', 'irrégulière', null, 'Cristaux lamellaires en « écriture », masses.', 'Filons hydrothermaux d''or-tellure (Cripple Creek, Colorado ; Kalgoorlie ; Săcărâmb, Roumanie).', 'De la Transylvanie, d''où provenaient les premiers échantillons.', null, 'Calavérite : plus jaune, sans argent notable. Or natif : malléable.', 'Tellurure d''or et d''argent, minerai d''or de certains gisements. Il s''altère en laissant des pellicules d''or.', null, false, 'published'),
  ('Calavérite', 'calaverite', 'AuTe₂', 'Monoclinique', 'Sulfures et sulfosels', 'rare', 2.5, 3, 9.1, 9.3, array['jaune laiton','blanc argenté']::text[], 'métallique', 'aucun', 'gris verdâtre', 'opaque', 'subconchoïdale', null, 'Cristaux striés, masses grenues.', 'Filons hydrothermaux de basse température (Cripple Creek, Kalgoorlie, Calaveras County).', 'Du comté de Calaveras (Californie).', null, 'Or natif : malléable, plus jaune. Pyrite : plus dure, moins dense.', 'Tellurure d''or, le plus courant des tellurures d''or, avec environ 40 % d''or. Il est à l''origine de la ruée vers l''or de Cripple Creek et de Kalgoorlie.', null, false, 'published'),
  ('Hessite', 'hessite', 'Ag₂Te', 'Monoclinique', 'Sulfures et sulfosels', 'rare', 2.5, 3, 8.2, 8.4, array['gris acier','gris plomb']::text[], 'métallique', 'aucun', 'gris noir', 'opaque', 'subconchoïdale', null, 'Masses, rares cristaux pseudo-cubiques.', 'Filons hydrothermaux riches en tellure (Roumanie, Colorado, Altaï).', 'De Germain Henri Hess (1802-1850), chimiste suisse-russe.', null, 'Argentite : se coupe au couteau, sans tellure.', 'Tellurure d''argent tendre, qui se coupe au couteau et accompagne souvent l''or.', null, false, 'published'),
  ('Pétzite', 'petzite', 'Ag₃AuTe₂', 'Cubique', 'Sulfures et sulfosels', 'tres_rare', 2.5, 3, 8.7, 9.4, array['gris acier','noir de fer']::text[], 'métallique', 'aucun', 'gris noir', 'opaque', 'subconchoïdale', null, 'Masses grenues, rares cristaux.', 'Filons hydrothermaux d''or-tellure (Cripple Creek, Kalgoorlie, Roumanie).', 'De W. Petz, qui l''analysa en 1845.', null, 'Hessite : sans or.', 'Tellurure d''or et d''argent gris acier, minerai d''or.', null, false, 'published'),
  ('Siegénite', 'siegenite', '(Ni,Co)₃S₄', 'Cubique', 'Sulfures et sulfosels', 'rare', 4.5, 5.5, 4.5, 4.8, array['gris acier','rose argenté']::text[], 'métallique', 'indistinct', 'gris noir', 'opaque', 'irrégulière', null, 'Octaèdres et masses grenues.', 'Filons hydrothermaux à nickel et cobalt (Siegerland, Katanga).', 'De Siegen (Allemagne).', null, 'Linnaéite : sans nickel notable. Pyrite : jaune, plus dure.', 'Sulfure de nickel et de cobalt, minerai de nickel de la région de Siegen.', null, false, 'published'),
  ('Greigite', 'greigite', 'Fe₃S₄', 'Cubique', 'Sulfures et sulfosels', 'rare', 4, 4, 4.0, 4.1, array['gris acier','violet sombre']::text[], 'métallique', 'indistinct', 'noir', 'opaque', 'irrégulière', null, 'Agrégats microscopiques.', 'Sédiments lacustres et marins pauvres en oxygène.', 'De Joseph W. Greig (1895-1977), minéralogiste américain.', null, 'Pyrite : jaune, non magnétique.', 'Sulfure de fer magnétique, produit par des bactéries qui s''orientent d''après le champ magnétique terrestre.', null, false, 'published'),
  ('Andorite', 'andorite', 'PbAgSb₃S₆', 'Orthorhombique', 'Sulfures et sulfosels', 'rare', 3, 3.5, 5.3, 5.4, array['gris d''acier','noir de fer']::text[], 'métallique', 'aucun', 'noir rougeâtre', 'opaque', 'subconchoïdale', null, 'Cristaux tabulaires, masses.', 'Filons à argent d''Oruro et de Potosí (Bolivie), Hongrie.', 'D''Andor von Semsey (1833-1923), minéralogiste hongrois.', null, 'Stéphanite : prismes plus courts.', 'Sulfosel de plomb, argent et antimoine, minerai d''argent des filons de Bolivie.', null, false, 'published'),
  ('Diaphorite', 'diaphorite', 'Pb₂Ag₃Sb₃S₈', 'Monoclinique', 'Sulfures et sulfosels', 'rare', 2.5, 3, 5.9, 6.0, array['gris acier','gris plomb']::text[], 'métallique', 'aucun', 'gris noir', 'opaque', 'irrégulière', null, 'Prismes striés, masses.', 'Filons à argent (Příbram, Bolivie, Idaho).', 'Du grec diaphora (différence), car elle diffère d''un minéral voisin, la freislébénite.', null, 'Pyrargyrite : trait rouge.', 'Sulfosel d''argent, de plomb et d''antimoine, minerai d''argent.', null, false, 'published'),
  ('Pearcéite', 'pearceite', '(Ag,Cu)₁₆As₂S₁₁', 'Monoclinique', 'Sulfures et sulfosels', 'tres_rare', 3, 3, 6.1, 6.2, array['noir de fer']::text[], 'métallique', 'aucun', 'noir', 'opaque', 'irrégulière', null, 'Tablettes hexagonales, masses.', 'Filons à argent (Colorado, Mexique, Chili).', 'De Richard Pearce (1837-1927), métallurgiste né en Cornouailles.', null, 'Polybasite : avec antimoine.', 'Sulfosel d''argent et d''arsenic, version arséniée de la polybasite.', null, false, 'published'),
  ('Plagionite', 'plagionite', 'Pb₅Sb₈S₁₇', 'Monoclinique', 'Sulfures et sulfosels', 'tres_rare', 2.5, 2.5, 5.4, 5.5, array['gris plomb','noir']::text[], 'métallique', 'parfait', 'gris noir', 'opaque', 'conchoïdale', null, 'Cristaux tabulaires, masses grenues.', 'Filons à plomb-antimoine (Wolfsberg, Harz).', 'Du grec plagios (oblique), pour ses cristaux obliques.', null, 'Boulangérite : fibreuse.', 'Sulfosel de plomb et d''antimoine, en tablettes obliques.', null, false, 'published'),
  ('Livingstonite', 'livingstonite', 'HgSb₄S₈', 'Monoclinique', 'Sulfures et sulfosels', 'tres_rare', 2, 2, 4.9, 5.0, array['gris plomb','rouge']::text[], 'métallique', 'parfait', 'rouge', 'opaque', 'irrégulière', null, 'Cristaux aciculaires et lamelles.', 'Gisements de mercure et d''antimoine (Huitzuco, Mexique).', 'De David Livingstone (1813-1873), explorateur écossais.', null, 'Stibine : sans mercure, trait gris. Cinabre : rouge vif.', 'Sulfure de mercure et d''antimoine, décrit à partir de la mine de Huitzuco au Mexique. Toxique : se laver les mains après manipulation.', null, false, 'published'),
  ('Lorandite', 'lorandite', 'TlAsS₂', 'Monoclinique', 'Sulfures et sulfosels', 'tres_rare', 2, 2.5, 5.5, 5.6, array['rouge cochenille','rouge sombre']::text[], 'adamantin', 'parfait', 'rouge cerise', 'translucide', 'irrégulière', null, 'Cristaux tabulaires, masses.', 'Gisement d''Allchar (Macédoine du Nord).', 'De Loránd Eötvös (1848-1919), physicien hongrois.', null, 'Réalgar : sans thallium.', 'Sulfosel de thallium et d''arsenic, spécialité d''Allchar, qui contient du thallium. Toxique : se laver les mains après manipulation.', null, false, 'published'),
  ('Boléite', 'boleite', 'KPb₂₆Ag₉Cu₂₄(OH)₄₈Cl₆₂', 'Cubique', 'Halogénures', 'tres_rare', 3, 3.5, 5.0, 5.1, array['bleu indigo','bleu foncé']::text[], 'vitreux nacré', 'parfait', 'bleu verdâtre', 'translucide', 'irrégulière', null, 'Cubes parfaits, souvent maclés avec la cumengéite.', 'Zone d''oxydation de gisements de cuivre-plomb-argent (Santa Rosalía, Boleo, Baja California).', 'De Boleo (Basse-Californie), la localité type.', null, 'Azurite : carbonate, effervescente. Cumengéite : quadratique.', 'Chlorure de plomb, de cuivre et d''argent d''un bleu indigo intense, en cubes parfaits parfois accolés à la cumengéite. Très recherché des collectionneurs.', null, false, 'published'),
  ('Cumengéite', 'cumengeite', 'Pb₂₁Cu₂₀Cl₄₂(OH)₄₀', 'Quadratique', 'Halogénures', 'tres_rare', 2.5, 2.5, 4.7, 4.8, array['bleu azur','bleu foncé']::text[], 'adamantin à vitreux', 'parfait', 'bleu clair', 'translucide', 'irrégulière', null, 'Cristaux tabulaires, souvent en épitaxie sur la boléite.', 'Zone d''oxydation de gisements de cuivre-plomb (Boleo, Baja California).', 'D''Édouard Cumenge (1828-1902), ingénieur des mines français, qui découvrit le gisement de Boléo.', null, 'Boléite : cubique, plus foncée.', 'Chlorure de plomb et de cuivre d''un bleu azur, formé de petits cristaux qui poussent sur les cubes de boléite.', null, false, 'published'),
  ('Baddeleyite', 'baddeleyite', 'ZrO₂', 'Monoclinique', 'Oxydes et hydroxydes', 'tres_rare', 6.5, 6.5, 5.4, 6.0, array['brun','jaune brun','noir']::text[], 'submétallique à vitreux', 'parfait', 'blanc', 'translucide à opaque', 'irrégulière', null, 'Cristaux tabulaires, grains.', 'Carbonatites et roches basiques (Kovdor, Russie ; Sri Lanka ; Phalaborwa).', 'De Joseph Baddeley, alpiniste britannique qui rapporta les premiers échantillons de Ceylan en 1892.', null, 'Zircon : tétragonal, silicate.', 'Oxyde de zirconium naturel, rare, utilisé par les géologues pour dater certaines roches.', null, false, 'published'),
  ('Hollandite', 'hollandite', 'Ba(Mn⁴⁺,Mn²⁺)₈O₁₆', 'Monoclinique', 'Oxydes et hydroxydes', 'rare', 6, 6.5, 4.7, 5.0, array['gris argenté','noir']::text[], 'submétallique', 'bon', 'brun noir', 'opaque', 'irrégulière', null, 'Aiguilles, masses fibreuses.', 'Gisements de manganèse et zones d''oxydation (Inde, Afrique du Sud, Ghana).', 'De Thomas Holland (1868-1947), directeur du Geological Survey of India.', null, 'Cryptomélane : analyse nécessaire.', 'Oxyde de manganèse et de baryum à structure en tunnels, dédié à un géologue britannique de l''Inde.', null, false, 'published'),
  ('Hétérogénite', 'heterogenite', 'CoO(OH)', 'Trigonal', 'Oxydes et hydroxydes', 'rare', 3, 4, 3.4, 4.0, array['noir','brun noir']::text[], 'submétallique à terne', 'parfait', 'brun noir', 'opaque', 'irrégulière', null, 'Masses botryoïdales et croûtes.', 'Zone d''oxydation des gisements de cuivre-cobalt (Katanga, RD Congo).', 'Du grec heterogenes (de nature différente), car sa composition étonna.', null, 'Pyrolusite : sans cobalt, trait noir.', 'Oxy-hydroxyde de cobalt noir, minerai de cobalt d''Afrique centrale.', null, false, 'published'),
  ('Tapiolite', 'tapiolite', '(Fe,Mn)(Ta,Nb)₂O₆', 'Quadratique', 'Oxydes et hydroxydes', 'rare', 6, 6.5, 7.9, 8.2, array['noir','brun noir']::text[], 'submétallique', 'indistinct', 'brun à noir', 'opaque', 'irrégulière', null, 'Cristaux courts, masses.', 'Pegmatites à lithium et tantale.', 'De Tapio, dieu finlandais des forêts.', null, 'Colombo-tantalite : orthorhombique.', 'Oxyde de tantale et de fer dense des pegmatites, quadratique alors que la tantalite est orthorhombique.', null, false, 'published'),
  ('Samarskite-(Y)', 'samarskite', '(Y,Fe³⁺,U)(Nb,Ta)O₄', 'Monoclinique', 'Oxydes et hydroxydes', 'rare', 5, 6, 5.4, 5.9, array['noir de velours','brun noir']::text[], 'résineux à submétallique', 'aucun', 'brun rouge', 'opaque', 'conchoïdale', null, 'Masses et cristaux grossiers.', 'Pegmatites granitiques (Caroline du Nord, Brésil, Madagascar).', 'De Vasili Samarsky-Bykhovets (1803-1870), ingénieur des mines russe.', null, 'Gadolinite : plus tendre.', 'Oxyde d''yttrium, de niobium et de tantale, qui a donné son nom au samarium. Souvent rendu amorphe par sa radioactivité. Radioactif : à conserver à l''écart, en boîte fermée.', null, false, 'published'),
  ('Fergusonite-(Y)', 'fergusonite', 'YNbO₄', 'Quadratique', 'Oxydes et hydroxydes', 'rare', 5.5, 6.5, 4.3, 5.8, array['brun noir','noir']::text[], 'vitreux à submétallique', 'indistinct', 'brun clair', 'opaque', 'conchoïdale', null, 'Prismes à section carrée, masses.', 'Pegmatites granitiques (Norvège, Madagascar, Texas).', 'De Robert Ferguson of Raith (1767-1840), collectionneur écossais.', null, 'Samarskite : sans clivage net, monoclinique.', 'Niobate d''yttrium des pegmatites, source de terres rares. Radioactif : à conserver à l''écart, en boîte fermée.', null, false, 'published'),
  ('Ikaïte', 'ikaite', 'CaCO₃·6H₂O', 'Monoclinique', 'Carbonates', 'tres_rare', 3, 3, 1.8, 1.8, array['incolore','blanc']::text[], 'vitreux', 'aucun', 'blanc', 'transparent', 'irrégulière', null, 'Colonnes et pointes de glace blanche.', 'Eaux froides (fjord d''Ikka, Groenland) ; sédiments polaires.', 'De l''Ikka Fjord (Groenland), où elle forme des colonnes sous-marines.', null, 'Gypse : plus stable.', 'Carbonate de calcium hydraté qui n''existe qu''à basse température : elle se décompose en calcite quand elle se réchauffe.', null, false, 'published'),
  ('Pirssonite', 'pirssonite', 'Na₂Ca(CO₃)₂·2H₂O', 'Orthorhombique', 'Carbonates', 'tres_rare', 3, 3.5, 2.35, 2.35, array['incolore','blanc']::text[], 'vitreux', 'parfait', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Cristaux pyramidaux, croûtes.', 'Lacs salés (Searles Lake, Californie ; Green River, Wyoming).', 'De Louis Valentine Pirsson (1860-1919), pétrographe américain.', null, 'Gaylussite : plus tendre.', 'Carbonate double de sodium et de calcium des lacs salés alcalins.', null, false, 'published'),
  ('Natron', 'natron', 'Na₂CO₃·10H₂O', 'Monoclinique', 'Carbonates', 'rare', 1, 1.5, 1.44, 1.47, array['incolore','blanc','jaunâtre']::text[], 'vitreux', 'parfait', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Croûtes et efflorescences.', 'Lacs salés alcalins (Wadi Natrun, Égypte ; lac Natron, Tanzanie).', 'De l''arabe natrun, via l''égyptien ancien.', null, 'Trona : moins hydraté.', 'Carbonate de sodium décahydraté, utilisé dès l''Antiquité égyptienne, notamment pour la momification. Il perd son eau à l''air.', null, false, 'published'),
  ('Artinite', 'artinite', 'Mg₂(CO₃)(OH)₂·3H₂O', 'Monoclinique', 'Carbonates', 'rare', 2.5, 2.5, 2.0, 2.03, array['blanc','incolore']::text[], 'soyeux à vitreux', 'parfait', 'blanc', 'transparent à translucide', 'irrégulière', null, 'Aiguilles et fibres en touffes rayonnantes.', 'Serpentinites altérées (Val Lanzo, Italie ; New York ; Californie).', 'D''Ettore Artini (1866-1928), minéralogiste italien.', null, 'Hydromagnésite : plus massive.', 'Carbonate hydraté de magnésium en gerbes d''aiguilles soyeuses sur les serpentinites.', null, false, 'published'),
  ('Ancylite-(Ce)', 'ancylite', 'SrCe(CO₃)₂(OH)·H₂O', 'Orthorhombique', 'Carbonates', 'tres_rare', 4, 4.5, 3.9, 4.0, array['jaune brun','brun rouge']::text[], 'vitreux à gras', 'aucun', 'jaune pâle', 'translucide', 'irrégulière', null, 'Cristaux en octaèdres aplatis, croûtes.', 'Pegmatites et carbonatites alcalines (Mont Saint-Hilaire, Québec ; Narsarsuk).', 'Du grec ankylos (courbé), pour ses cristaux aux faces arquées.', null, 'Bastnäsite : hexagonal.', 'Carbonate de strontium et de cérium des roches alcalines.', null, false, 'published'),
  ('Synchysite-(Ce)', 'synchysite', 'CaCe(CO₃)₂F', 'Monoclinique', 'Carbonates', 'tres_rare', 4.5, 4.5, 3.9, 4.0, array['jaune miel','brun jaune']::text[], 'vitreux à résineux', 'aucun', 'blanc', 'translucide', 'irrégulière', null, 'Cristaux en fuseaux, souvent en intercroissance.', 'Pegmatites et carbonatites (Norvège, Malawi, Zagi, Pakistan).', 'Du grec synchysis (confusion), car on le confondait avec la parisite.', null, 'Parisite : voir sa fiche.', 'Fluocarbonate de calcium et de cérium, voisin de la bastnäsite et de la parisite.', null, false, 'published'),
  ('Stichtite', 'stichtite', 'Mg₆Cr₂(CO₃)(OH)₁₆·4H₂O', 'Trigonal', 'Carbonates', 'rare', 1.5, 2, 2.16, 2.2, array['rose','lilas','violet']::text[], 'gras à nacré', 'parfait', 'blanc rosé', 'translucide', 'irrégulière', null, 'Masses lamellaires à écailles.', 'Serpentinites à chromite (Tasmanie, Afrique du Sud, Canada).', 'De Robert Sticht (1856-1922), directeur de la mine de Mount Lyell (Tasmanie).', null, 'Lépidolite : plus dure, en paillettes.', 'Carbonate de magnésium et de chrome, rose lilas, associé à la serpentine verte dans des pierres ornementales (« atlantisite »).', null, false, 'published'),
  ('Syngénite', 'syngenite', 'K₂Ca(SO₄)₂·H₂O', 'Monoclinique', 'Sulfates, chromates, molybdates et tungstates', 'rare', 2.5, 2.5, 2.57, 2.58, array['incolore','blanc','jaunâtre']::text[], 'vitreux', 'parfait', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Cristaux tabulaires ou en prismes.', 'Évaporites potassiques (Kalusz, Ukraine ; Stassfurt, Allemagne).', 'Du grec syn (avec) et genesis (formation), pour son association avec d''autres sels.', null, 'Gypse : sans potassium, plus tendre.', 'Sulfate de potassium et de calcium des gisements de sels de potasse.', null, false, 'published'),
  ('Blödite', 'bloedite', 'Na₂Mg(SO₄)₂·4H₂O', 'Monoclinique', 'Sulfates, chromates, molybdates et tungstates', 'rare', 2.5, 3, 2.25, 2.28, array['incolore','vert pâle','rougeâtre']::text[], 'vitreux', 'aucun', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Cristaux courts, masses granuleuses.', 'Évaporites et lacs salés (Ischl, Autriche ; Searles Lake).', 'De Carl August Blöde (1773-1820), chimiste allemand.', null, 'Épsomite : plus soluble.', 'Sulfate double de sodium et de magnésium des dépôts salins.', null, false, 'published'),
  ('Langbeinite', 'langbeinite', 'K₂Mg₂(SO₄)₃', 'Cubique', 'Sulfates, chromates, molybdates et tungstates', 'rare', 3.5, 4, 2.82, 2.83, array['incolore','blanc','jaunâtre','rose']::text[], 'vitreux', 'aucun', 'blanc', 'transparent', 'conchoïdale', null, 'Cristaux tétraédriques, masses.', 'Évaporites de potasse (Carlsbad, Nouveau-Mexique ; Stassfurt).', 'D''Albert Langbein, chimiste allemand du XIXe siècle.', null, 'Sylvite : cubique, plus tendre.', 'Sulfate de potassium et de magnésium, exploité comme engrais.', null, false, 'published'),
  ('Spangolite', 'spangolite', 'Cu₆Al(SO₄)(OH)₁₂Cl·3H₂O', 'Trigonal', 'Sulfates, chromates, molybdates et tungstates', 'tres_rare', 2, 3, 3.1, 3.14, array['vert profond','vert bleuté']::text[], 'vitreux', 'parfait', 'vert pâle', 'transparent à translucide', 'irrégulière', null, 'Petits cristaux hexagonaux en pyramides.', 'Zone d''oxydation de gisements de cuivre (Bisbee, Arizona).', 'De Norman Spang (XIXe siècle), collectionneur de Pennsylvanie.', null, 'Brochantite : sans aluminium ni chlore.', 'Chlorosulfate de cuivre et d''aluminium d''un vert intense, recherché pour ses petits cristaux géométriques.', null, false, 'published'),
